message.content:
- Failures recur as exhaustive search after seeing a target, carrying the wrong item, or taking back an already placed target.
- Maintain reusable stages: find_target, take_target, transform, go_destination, put_target, wrong_inventory, plus placed_count for pick_two.
- on_init gives task order; on_post_step updates stage from task/world/action/observation; make_pre_hint gives deduped subgoal hints; on_before_action blocks only narrow wrong puts or taking back placed items.
- Avoided numbered forced actions and broad forcing, so successful trajectories and wrong-inventory cases are not disrupted.
</think>
<patch>{
  "benchmark": "alfworld",
  "description": "Add staged ALFWorld guidance for target carrying, transformation, placement, and pick-two reuse.",
  "actions": [
    {
      "type": "add_code_hook",
      "hook": "on_init",
      "code": "def hook(ctx, nb):
    nb['stage'] = 'find_target'
    nb['placed_count'] = 0
    nb['last_hint'] = ''
    nb['holding_target'] = False
    nb['transformed'] = False
    nb['placed_items'] = []
    nb['placed_locations'] = []
    text = 'Follow this order: find the target object, take it, do any required clean heat cool or slice step while carrying it, then carry it to the destination and put it there. For two-object tasks, leave placed items and use the same destination.'
    return {'skills': [{'text': text}], 'tool_hint': 'Track inventory, required transform, and destination instead of searching every container after the target appears.'}"
    },
    {
      "type": "add_code_hook",
      "hook": "on_post_step",
      "code": "def as_text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([as_text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([as_text(k) + ' ' + as_text(v) for k, v in x.items()])
    return str(x).lower()

def need_verb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def has_word(text, word):
    return bool(word and word in text)

def hook(ctx, nb):
    world = ctx.get('world') or {}
    task = ctx.get('task') or {}
    actd = ctx.get('action') or {}
    action = ''
    if isinstance(actd, dict) and actd.get('final_action'):
        action = str(actd.get('final_action') or actd.get('normalized') or actd.get('raw') or '')
    elif isinstance(actd, dict) and actd.get('normalized'):
        action = str(actd.get('normalized') or actd.get('raw') or '')
    elif actd:
        action = str(actd)
    action = as_text(action)
    if 'placed_items' not in nb:
        nb['placed_items'] = []
    if 'placed_locations' not in nb:
        nb['placed_locations'] = []
    target = task.get('target_type') or ''
    dest = task.get('destination_type') or ''
    tt = as_text(task.get('task_type') or ctx.get('task.task_type') or '')
    verb = need_verb(tt)
    admiss = ctx.get('admissible') or []
    inv = as_text(world.get('inventory') or ctx.get('world.inventory') or '')
    if 'nothing' in inv and 'not carrying' in inv:
        inv = ''
    if target and action.startswith('take ') and has_word(action, target):
        nb['holding_target'] = True
        nb['wrong_inventory'] = False
    if target and action.startswith('put ') and has_word(action, target):
        nb['holding_target'] = False
    if target and verb and target in action and action.startswith(verb + ' '):
        nb['transformed'] = True
    pc = world.get('placed_count')
    if isinstance(pc, int) and pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    elif action.startswith('put ') and has_word(action, target) and dest and has_word(action, dest):
        item = action[4:]
        loc = item
        if ' in/on ' in item:
            parts = item.split(' in/on ')
            item = parts[0]
            loc = parts[1]
        if item and item not in nb['placed_items']:
            nb['placed_items'].append(item)
        if loc and loc not in nb['placed_locations']:
            nb['placed_locations'].append(loc)
        nb['placed_count'] = len(nb['placed_items'])
    carrying = bool(inv and 'nothing' not in inv and 'not carrying' not in inv)
    holding = carrying and (not target or has_word(inv, target))
    if holding and verb and not nb.get('transformed') and verb != 'slice':
        nb['stage'] = 'transform'
    elif carrying and target and not has_word(inv, target):
        nb['stage'] = 'wrong_inventory'
    elif holding and (not verb or nb.get('transformed')):
        if dest and has_word(action, dest) and action.startswith('put '):
            nb['stage'] = 'placed'
        else:
            nb['stage'] = 'go_destination'
    else:
        take_ok = False
        for a in admiss:
            if target and as_text(a).startswith('take ') and has_word(as_text(a), target):
                take_ok = True
        if take_ok and not holding and not (carrying and target and not has_word(inv, target)):
            nb['stage'] = 'take_target'
        else:
            nb['stage'] = 'find_target'
    nb['holding_target'] = holding
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['verb'] = verb
    return None"
    },
    {
      "type": "add_code_hook",
      "hook": "make_pre_hint",
      "code": "def hook(ctx, nb):
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    stage = nb.get('stage')
    verb = nb.get('verb')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it at the goal; recover the ' + target + ' instead.'
    elif stage == 'take_target':
        msg = 'The ' + target + ' is available here. Take the target before continuing to search.'
    elif stage == 'transform' and verb:
        if verb in ['clean', 'heat', 'cool']:
            msg = 'Carry the ' + target + ' to the ' + verb + ' station and use the ' + verb + ' action before placing it.'
        else:
            msg = 'Carry the ' + target + ' and use the required ' + verb + ' action before placing it.'
    elif stage == 'go_destination':
        msg = 'Carry the ' + target + ' to the ' + dest + ' and put it there; do not put it on unrelated surfaces.'
    elif stage == 'find_target' and 'two' in (nb.get('task_type') or '') and nb.get('placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + '.'
    if not msg or msg == nb.get('last_hint'):
        return None
    nb['last_hint'] = msg
    return {'message': msg}"
    },
    {
      "type": "add_code_hook",
      "hook": "on_before_action",
      "code": "def as_text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([as_text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([as_text(k) + ' ' + as_text(v) for k, v in x.items()])
    return str(x).lower()

def need_verb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def has_word(text, word):
    return bool(word and word in text)

def hook(ctx, nb):
    world = ctx.get('world') or {}
    task = ctx.get('task') or {}
    actd = ctx.get('action') or {}
    action = ''
    if isinstance(actd, dict) and actd.get('final_action'):
        action = str(actd.get('final_action') or actd.get('normalized') or actd.get('raw') or '')
    elif isinstance(actd, dict) and actd.get('normalized'):
        action = str(actd.get('normalized') or actd.get('raw') or '')
    elif actd:
        action = str(actd)
    action = as_text(action)
    if not action:
        return None
    target = nb.get('target_type') or task.get('target_type') or ''
    dest = nb.get('destination_type') or task.get('destination_type') or ''
    tt = as_text(task.get('task_type') or ctx.get('task.task_type') or '')
    verb = need_verb(tt)
    admiss = ctx.get('admissible') or []
    inv = as_text(world.get('inventory') or ctx.get('world.inventory') or '')
    if 'nothing' in inv and 'not carrying' in inv:
        inv = ''
    carrying = bool(inv and 'nothing' not in inv and 'not carrying' not in inv)
    holding = carrying and (not target or has_word(inv, target))
    non_target = carrying and target and not has_word(inv, target)
    if non_target and action.startswith('put ') and (not dest or has_word(action, dest)) and not (has_word(action, target) or has_word(action, 'target')):
        return {'kind': 'block_and_prompt', 'message': 'This is not the target object. Do not place a non-target item at the goal; recover the target instead.'}
    if 'two' in (nb.get('task_type') or '') and target and action.startswith('take ') and has_word(action, target) and nb.get('placed_count', 0) > 0:
        items = nb.get('placed_items') or []
        for item in items:
            if item and item in action and item not in action.split(' from ')[-1]:
                return {'kind': 'block_and_prompt', 'message': 'Do not take back an already placed target. Leave it there and find another target for the same destination.'}
    if target and action.startswith('put ') and has_word(action, target) and dest and not has_word(action, dest) and verb and not nb.get('transformed') and (holding or (not carrying and target in action)):
        if action in admiss or (not carrying and target in action and any(a.startswith('put ') and has_word(a, target) for a in admiss)):
            return {'kind': 'block_and_prompt', 'message': 'This target still needs its required ' + verb + ' step before being placed. Go to the transform station first.'}
    return None"
    }
  ]
